/* lignes de la liste : un cours, ses sections, un document par ligne */
.tx-groupe { display: flex; flex-direction: column; gap: 6px; }
.tx-groupe-titre { margin: 8px 0 0; font-size: 12.5px; font-weight: 620; color: var(--texte-2); }
.tx-groupe-titre span + span::before { content: "·"; margin-right: 6px; color: var(--texte-2); }
.tx-lignes { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 4px; }
.tx-ligne { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; column-gap: 10px;
  padding: 8px 10px; border: 1px solid var(--bord); border-radius: 8px; background: var(--surface); }
.tx-ligne-tete { display: flex; align-items: center; gap: 8px; min-width: 0; flex-wrap: wrap; }
.tx-nom { font-size: 13px; color: var(--texte); overflow-wrap: anywhere; }
.tx-badges { display: inline-flex; align-items: center; gap: 5px; flex-wrap: wrap; }
.tx-meta { display: flex; align-items: center; gap: 8px; margin: 2px 0 0; font-size: 12px; color: var(--texte-2); }
.tx-meta > span + span::before { content: "·"; margin-right: 8px; color: var(--texte-2); }
.tx-ligne-actions { position: relative; display: flex; align-items: center; gap: 6px; grid-row: 1 / span 2; grid-column: 2; }

/* menu d'une ligne et menu des actions principales */
.tx-actions { position: relative; }
.tx-menu { position: absolute; top: calc(100% + 4px); right: 0; z-index: 6; min-width: 190px;
  display: flex; flex-direction: column; gap: 1px; padding: 4px; border: 1px solid var(--bord);
  border-radius: 8px; background: var(--carte); box-shadow: var(--ombre-haute); }
.tx-menu-titre { margin: 4px 8px 6px; font-size: 12px; font-weight: 600; color: var(--texte-2); }
.tx-menu-vide { margin: 4px 8px 6px; font-size: 12.5px; color: var(--texte-2); }
.tx-menu button { text-align: left; border: 0; background: none; padding: 7px 9px; border-radius: 6px;
  font-size: 13px; color: var(--texte); cursor: pointer; }
.tx-menu button:hover { background: var(--surface); }

/* resultats de recherche */
.tx-trouves { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 6px; }
.tx-trouves:empty { display: none; }
.tx-trouve { display: flex; flex-direction: column; gap: 4px; align-items: flex-start; padding: 8px 10px;
  border: 1px solid var(--bord); border-radius: 8px; background: var(--surface); cursor: pointer; }
.tx-trouve-tete { display: flex; align-items: baseline; gap: 8px; flex-wrap: wrap; font-size: 12px; color: var(--texte-2); }
.tx-trouve-tete .tx-nom { font-size: 12.5px; }
.tx-extrait { margin: 0; font-size: 12.5px; color: var(--texte-2); overflow-wrap: anywhere; }
.tx-extrait mark { background: var(--accent-doux); color: var(--texte); border-radius: 3px; padding: 0 1px; }

/* dialogue de qualite */
.tx-qualite { display: flex; flex-direction: column; gap: 6px; }
.tx-qualite-ligne { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; padding: 6px 8px;
  border: 1px solid var(--bord); border-radius: 8px; background: var(--surface); }
.tx-qualite-ligne .tx-lieu { font-size: 12px; color: var(--texte-2); }

@media (max-width: 680px) {
  .tx-ligne { grid-template-columns: minmax(0, 1fr); }
  .tx-ligne-actions { grid-row: auto; grid-column: 1; justify-content: flex-start; }
}

